ValidationRule.errorConditionFormula:
AND(
  /* Specific PriceBooks by record type was not implemented until mid April 2026, so opportunities created before this time should not receive an error*/
  CreatedDate > DATETIMEVALUE("2026-04-15 00:00:00"),
  OR(
    /* Agency Opportunities must have the Agency Price Book */
    AND(
      RecordType.DeveloperName = "Agency",
      Pricebook2.Name <> "Agency Price Book"
    ),
    /* Accelerated Opportunities must have the Accelerated Price Book*/
    AND(
      RecordType.DeveloperName = "Accelerated",
      Pricebook2.Name <> "Accelerated Price Book"
    ),
    /* CS Upsell on an Accelerated Account must have the Accelerated Price Book */
    AND(
      RecordType.DeveloperName = "CS_Upsell",
      Account.RecordType.DeveloperName = "Accelerated",
      Pricebook2.Name <> "Accelerated Price Book"
    ),
    /* CS Upsell on an Agency Account must have an Agency Price Book*/
    AND(
      RecordType.DeveloperName = "CS_Upsell",
      Account.RecordType.DeveloperName = "Agency",
      Pricebook2.Name <> "Agency Price Book"
    )
  )
)
